1	import type { McpServer } from '@modelcontextprotocol/server';
2	import type { Sink } from './sinks/types.js';
3	import { ERROR_KIND_META_KEY, type ToolCallEvent } from './events.js';
4	import { parseTraceparent } from './trace-context.js';
5	import { classifyError, isErrorKind } from './error-kind.js';
6	import { applyRedaction, type RedactionConfig } from './redaction.js';
7	import {
8	  extractAndStripIntent,
9	  injectIntentSchema,
10	  isIntentCaptureEnabled,
11	  schemaSupportsInjection,
12	  type IntentCaptureOption
13	} from './intent-capture.js';
14	import { EventBuffer } from './buffer.js';
15	import { boundedString, MAX_IDENTIFIER_LENGTH } from './bounded.js';
16	
17	export interface InstrumentOptions {
18	  /** Required: this server's logical name. Not derivable from the McpServer instance (its `serverInfo` is private), so it's an explicit option. */
19	  serverName: string;
20	  serverVersion?: string;
21	  sinks: Sink[];
22	  /** Opt-in: capture tool arguments at all. Default false — no arguments are ever recorded unless this is true. */
23	  captureArguments?: boolean;
24	  redaction?: RedactionConfig;
25	  /** Opt-in: inject session_id/agent_id/intent into advertised tool schemas. Default false (off for every tool). */
26	  intentCapture?: IntentCaptureOption;
27	  /** Host-supplied user/org identity. The library never infers these itself. */
28	  resolveIdentity?: (ctx: {
29	    sessionId?: string;
30	  }) =>
31	    | { userId?: string; orgId?: string }
32	    | undefined
33	    | Promise<{ userId?: string; orgId?: string } | undefined>;
34	  bufferSize?: number;
35	  /** Pass `null` for manual mode: no interval timer, no `beforeExit` listener — flush explicitly via the returned handle's `flush()`. */
36	  flushIntervalMs?: number | null;
37	}
38	
39	/**
40	 * Returned by `instrument()`. `server` is the same instance passed in
41	 * (instrumentation mutates it in place); use the handle's `server` rather
42	 * than your own pre-instrument reference so a future non-mutating
43	 * implementation doesn't silently drop instrumentation under you.
44	 */
45	export interface InstrumentHandle {
46	  server: McpServer;
47	  /** Flushes any buffered events immediately. On a request-scoped runtime (e.g. Cloudflare Workers), call this via `ctx.waitUntil(handle.flush())` before returning the response. */
48	  flush(): Promise<void>;
49	  /**
50	   * Shuts instrumentation down: a final `flush()`, then the interval timer
51	   * is cleared and the `beforeExit` listener removed. Call it when the host
52	   * disposes the server before the process ends - tests, hot reload, one
53	   * server per connection - so each `instrument()` call releases what it
54	   * registered. Idempotent. In manual mode (`flushIntervalMs: null`) there
55	   * is no timer or listener, so it is equivalent to `flush()`.
56	   */
57	  close(): Promise<void>;
58	}
59	
60	interface ToolCallContext {
61	  sessionId?: string;
62	  http?: unknown;
63	  mcpReq?: {
64	    id?: unknown;
65	    /** The request `_meta`, with the reserved `io.modelcontextprotocol/*` keys lifted into `envelope`. */
66	    _meta?: Record<string, unknown>;
67	    envelope?: Record<string, unknown>;
68	  };
69	}
70	
71	interface ToolResultLike {
72	  content?: Array<{ type: string; text?: string }>;
73	  isError?: boolean;
74	  resultType?: unknown;
75	  _meta?: Record<string, unknown>;
76	}
77	
78	/** The part of McpServer's `RegisteredTool` this file reads. Its `annotations` change on `update()`. */
79	interface RegisteredToolLike {
80	  annotations?: { readOnlyHint?: unknown; destructiveHint?: unknown };
81	}
82	
83	const PROTOCOL_VERSION_META_KEY = 'io.modelcontextprotocol/protocolVersion';
84	
85	/** JSON-RPC's code for an error with no code of its own, as the SDK answers it. */
86	const INTERNAL_ERROR_CODE = -32603;
87	
88	function booleanOrNull(value: unknown): boolean | null {
89	  return typeof value === 'boolean' ? value : null;
90	}
91	
92	interface ToolsCallRequest {
93	  params?: { name?: unknown; arguments?: unknown };
94	}
95	
96	type ToolsCallHandler = (request: ToolsCallRequest, ctx: ToolCallContext) => unknown;
97	
98	/** The intent-capture values a call carried, and its arguments without them. */
99	interface IntentFields {
100	  clean: Record<string, unknown>;
101	  session_id: string | null;
102	  agent_id: string | null;
103	  intent: string | null;
104	}
105	
106	function extractIntentFields(args: Record<string, unknown>): IntentFields {
107	  return extractAndStripIntent(args);
108	}
109	
110	function noIntentFields(args: Record<string, unknown>): IntentFields {
111	  return { clean: args, session_id: null, agent_id: null, intent: null };
112	}
113	
114	function isRecord(value: unknown): value is Record<string, unknown> {
115	  return typeof value === 'object' && value !== null && !Array.isArray(value);
116	}
117	
118	// TextEncoder rather than Buffer.byteLength: this runs on every tool call,
119	// and Buffer only exists on Cloudflare Workers behind the nodejs_compat flag.
120	const encoder = new TextEncoder();
121	
122	function byteLength(value: unknown): number {
123	  return encoder.encode(JSON.stringify(value) ?? '').length;
124	}
125	
126	/**
127	 * Proves the recorded arguments survive JSON encoding, or throws.
128	 *
129	 * Every sink re-serializes `arguments` on its way out - `JSON.stringify` in
130	 * console/d1/bigquery, `pg`'s own jsonb encoder in postgres - and a value
131	 * that cannot be encoded makes that whole `write()` throw. EventBuffer
132	 * catches the throw, so the server is never affected, but the entire batch
133	 * is dropped with it, including the unrelated events flushed alongside.
134	 * Checking here means one bad value costs one event's `arguments`, never a
135	 * whole flush.
136	 *
137	 * Only a `redaction.redactor` or a `redaction.allow` entry can produce such
138	 * a value: the default type-only markers are always encodable. The extra
139	 * `JSON.stringify` therefore runs only when argument capture is on, and not
140	 * at all on the default path, where `value` is null.
141	 */
142	function assertSerializable(value: Record<string, unknown> | null): Record<string, unknown> | null {
143	  if (value === null) return null;
144	  JSON.stringify(value); // throws on a BigInt, a circular reference, or a throwing toJSON
145	  return value;
146	}
147	
148	function extractErrorMessage(result: ToolResultLike): string | null {
149	  const text = (result.content ?? [])
150	    .filter(
151	      (block): block is { type: 'text'; text: string } =>
152	        block.type === 'text' && typeof block.text === 'string'
153	    )
154	    .map(block => block.text)
155	    .join(' ');
156	  if (!text) return null;
157	  return text.length > 2000 ? text.slice(0, 2000) : text;
158	}
159	
160	/**
161	 * Wraps an `McpServer` so every tool registered through it (after this call)
162	 * records a `tool_call` event. This is the library's one required call —
163	 * call it immediately after constructing the server and before registering
164	 * any tools, since it works by wrapping `registerTool` and the `tools/call`
165	 * handler McpServer installs on its first registration.
166	 *
167	 * Every `tools/call` the server answers is recorded, including ones that
168	 * never reach a tool callback: an unknown or disabled tool, and arguments
169	 * that fail the tool's `inputSchema`. `success` follows the result the
170	 * client receives, so a result McpServer rejects against `outputSchema` is
171	 * recorded as failed.
172	 *
173	 * Nothing the library does around a tool call can change what the client
174	 * receives. The real handler always runs, its return value is passed through
175	 * unchanged, and a thrown error is re-thrown unchanged; this wrapper only
176	 * observes it. Every library-side step (request/response byte counting,
177	 * `resolveIdentity`, redaction, event construction, the buffer push) is
178	 * guarded: a failure is logged once per `instrument()` call via
179	 * `console.error`, then suppressed, and the step falls back to a neutral
180	 * value (`request_bytes`/`response_bytes` 0, empty identity, `arguments:
181	 * null`). A failing redactor therefore records `arguments: null`, never the
182	 * raw arguments. A failure inside a sink is handled separately by
183	 * EventBuffer, also logged once per sink.
184	 */
185	export function instrument(server: McpServer, options: InstrumentOptions): InstrumentHandle {
186	  const buffer = new EventBuffer({
187	    sinks: options.sinks,
188	    bufferSize: options.bufferSize,
189	    flushIntervalMs: options.flushIntervalMs
190	  });
191	
192	  // Same "log once, then suppress" pattern EventBuffer uses per sink, scoped
193	  // to this instrument() call: one line is enough to surface a broken
194	  // resolver or redactor, and a line per tool call would drown the host's logs.
195	  let telemetryWarned = false;
196	  const warnOnce = (step: string, error: unknown): void => {
197	    if (telemetryWarned) return;
198	    telemetryWarned = true;
199	    console.error(
200	      `[mcpsignals] ${step} failed; the tool result is unaffected and further telemetry errors from this instrument() call are suppressed:`,
201	      error
202	    );
203	  };
204	  /** Runs one library-side step; on a throw, logs once and returns `fallback`. */
205	  const guarded = <T>(step: string, fn: () => T, fallback: T): T => {
206	    try {
207	      return fn();
208	    } catch (error) {
209	      warnOnce(step, error);
210	      return fallback;
211	    }
212	  };
213	  /** `guarded` for an async step: a throw or a rejection logs once and yields `fallback`. */
214	  const guardedAsync = async <T>(step: string, fn: () => Promise<T>, fallback: T): Promise<T> => {
215	    try {
216	      return await fn();
217	    } catch (error) {
218	      warnOnce(step, error);
219	      return fallback;
220	    }
221	  };
222	
223	  /**
224	   * What the tool callback saw, handed from the `registerTool` wrapper to the
225	   * `tools/call` recorder below. Keyed by the request's `ctx`: McpServer
226	   * passes its `tools/call` handler's `ctx` straight through to the tool
227	   * callback, so both layers see the same object.
228	   */
229	  const handlerCalls = new WeakMap<object, IntentFields>();
230	  /** Registered tool name -> whether intent capture injected its schema, and the SDK's tool object. */
231	  const registeredTools = new Map<string, { canInject: boolean; tool?: RegisteredToolLike }>();
232	
233	  const originalRegisterTool = server.registerTool.bind(server);
234	
235	  server.registerTool = ((
236	    name: string,
237	    config: Record<string, unknown>,
238	    cb: (...args: unknown[]) => unknown
239	  ) => {
240	    const intentEnabled = isIntentCaptureEnabled(options.intentCapture, name);
241	    const originalInputSchema = config.inputSchema;
242	    const canInject = intentEnabled && schemaSupportsInjection(originalInputSchema);
243	    const registration: { canInject: boolean; tool?: RegisteredToolLike } = { canInject };
244	    registeredTools.set(name, registration);
245	
246	    const wrappedConfig = canInject
247	      ? { ...config, inputSchema: injectIntentSchema(originalInputSchema) }
248	      : config;
249	
250	    /** Strips injected intent-capture keys and leaves them for the recorder. */
251	    const prepare = (args: Record<string, unknown>, ctx: ToolCallContext) => {
252	      const fields = canInject ? extractIntentFields(args) : noIntentFields(args);
253	      handlerCalls.set(ctx, fields);
254	      return fields.clean;
255	    };
256	
257	    // The SDK's `createToolExecutor` picks the handler arity from the registered
258	    // `inputSchema` (same truthiness check as here): with a schema it calls
259	    // `(args, ctx)`; without one it calls `(ctx)` and never forwards the
260	    // arguments. The wrapper has to match that arity, otherwise the schema-less
261	    // handler gets the ctx object in `args` and `undefined` in `ctx`. Branch on
262	    // the final `wrappedConfig.inputSchema`, since intent capture may have
263	    // injected a schema into a registration that had none.
264	    //
265	    // On the schema-less path the SDK does not validate or pass the arguments,
266	    // so `arguments` is recorded as an empty-arguments call (`{}`) rather than
267	    // a payload the handler never sees.
268	    const wrappedCb = wrappedConfig.inputSchema
269	      ? async (args: Record<string, unknown>, ctx: ToolCallContext) => cb(prepare(args, ctx), ctx)
270	      : async (ctx: ToolCallContext) => {
271	          prepare({}, ctx);
272	          return cb(ctx);
273	        };
274	
275	    // The real `registerTool` overloads are exact per input/output schema shape; a
276	    // generic wrapper can't preserve that precision through a monkey-patch, so we
277	    // widen to `any` at this one call site rather than fighting the overload set.
278	    const tool = (originalRegisterTool as (...args: unknown[]) => unknown)(
279	      name,
280	      wrappedConfig,
281	      wrappedCb
282	    );
283	    // Read at call time, not now, so `RegisteredTool.update({ annotations })` is honored.
284	    registration.tool = tool as RegisteredToolLike;
285	    return tool;
286	  }) as typeof server.registerTool;
287	
288	  /**
289	   * Runs one `tools/call` request with telemetry around it. This wraps the
290	   * handler McpServer registers, not the tool callback, so it sees what the
291	   * client sees: an unknown or disabled tool (a JSON-RPC error), an
292	   * input-schema failure (an `isError` result, callback never runs), and an
293	   * output-schema failure (an `isError` result, callback already returned
294	   * success). A tool callback that throws reaches this layer as McpServer's
295	   * `isError` result carrying the error message.
296	   */
297	  const observeToolsCall = async (
298	    request: ToolsCallRequest,
299	    ctx: ToolCallContext,
300	    handler: ToolsCallHandler
301	  ) => {
302	    const startedAt = new Date();
303	    const start = performance.now();
304	
305	    const params = request?.params ?? {};
306	    const rawName = typeof params.name === 'string' ? params.name : '';
307	    const rawArgs = params.arguments ?? {};
308	    // `JSON.stringify` throws on a BigInt (and on a throwing `toJSON`);
309	    // an unmeasurable request is recorded as 0 bytes, never blocks the handler.
310	    const requestBytes = guarded('request byte count', () => byteLength(rawArgs), 0);
311	
312	    /**
313	     * Builds and pushes the event. Every caller wraps this in `guardedAsync`,
314	     * so a failure anywhere in here (identity, client info, redaction, the
315	     * buffer push) is logged once and the event is dropped, never surfaced
316	     * to the client. Redaction and `resolveIdentity` are guarded on their
317	     * own so a broken redactor or resolver still leaves an event behind,
318	     * recorded with `arguments: null` / a null identity.
319	     *
320	     * `durationMs` is measured by the caller the moment the handler settles.
321	     * `resolveIdentity` runs in here, after the handler, so its latency is
322	     * outside the timed window: `duration_ms` is wall time from call start
323	     * to response, per schema/events.md.
324	     */
325	    const push = async (
326	      durationMs: number,
327	      partial: Pick<
328	        ToolCallEvent,
329	        'success' | 'error_kind' | 'error_message' | 'response_bytes' | 'result_type' | 'error_code'
330	      >
331	    ) => {
332	      const registration = registeredTools.get(rawName);
333	      // The callback's view when it ran. When it never ran, read the raw
334	      // arguments the way it would have, so a rejected call still records intent.
335	      const rawRecord = isRecord(rawArgs) ? rawArgs : {};
336	      const fields =
337	        handlerCalls.get(ctx) ??
338	        (registration?.canInject ? extractIntentFields(rawRecord) : noIntentFields(rawRecord));
339	
340	      // Revision 2026-07-28 carries the version on every request's envelope;
341	      // earlier revisions negotiate it once in `initialize`. Either way the
342	      // client supplied it, so it takes the identifier cap. The accessor is
343	      // deprecated for the same reason as getClientVersion() below and is
344	      // only the fallback for a request with no envelope.
345	      const protocolVersion = boundedString(
346	        ctx.mcpReq?.envelope?.[PROTOCOL_VERSION_META_KEY] ??
347	          server.server.getNegotiatedProtocolVersion(),
348	        MAX_IDENTIFIER_LENGTH
349	      );
350	      const requestId = ctx.mcpReq?.id;
351	      // `_meta` is the MCP protocol's field name.
352	      // oxlint-disable-next-line no-underscore-dangle
353	      const trace = parseTraceparent(ctx.mcpReq?._meta?.traceparent);
354	      const annotations = registration?.tool?.annotations;
355	
356	      // A host resolver that throws or rejects records a null identity.
357	      let identity: { userId?: string; orgId?: string } = {};
358	      try {
359	        identity = (await options.resolveIdentity?.({ sessionId: ctx.sessionId })) ?? {};
360	      } catch (error) {
361	        warnOnce('resolveIdentity', error);
362	      }
363	      // getClientVersion() is deprecated in favor of reading client identity off the
364	      // per-request `_meta` envelope, but the SDK's own deprecation note says the accessor
365	      // "remains functional" and is backfilled per request on 2026-07-28-era connections too.
366	      // Deliberately kept rather than reaching into the envelope's internal shape, which isn't
367	      // part of this SDK's stable public surface yet.
368	      //
369	      // The client declares its own name/version in the `initialize` handshake, so
370	      // both are caller-controlled and take the same identifier cap as the intent
371	      // fields (see bounded.ts).
372	      const clientInfo = server.server.getClientVersion();
373	      const clientName = boundedString(clientInfo?.name, MAX_IDENTIFIER_LENGTH);
374	      const clientVersion = boundedString(clientInfo?.version, MAX_IDENTIFIER_LENGTH);
375	      const recordedArguments = guarded(
376	        'redaction',
377	        () =>
378	          assertSerializable(
379	            applyRedaction(fields.clean, options.redaction, options.captureArguments)
380	          ),
381	        null
382	      );
383	      buffer.push({
384	        event_type: 'tool_call',
385	        ts: startedAt,
386	        server_name: options.serverName,
387	        server_version: options.serverVersion ?? null,
388	        // A registered name is the server's own. Any other name came from the
389	        // client, so it takes the identifier cap.
390	        tool_name: registeredTools.has(rawName)
391	          ? rawName
392	          : (boundedString(rawName, MAX_IDENTIFIER_LENGTH) ?? ''),
393	        session_id: ctx.sessionId ?? fields.session_id,
394	        agent_id: fields.agent_id,
395	        client_name: clientName,
396	        client_version: clientVersion,
397	        user_id: identity.userId ?? null,
398	        org_id: identity.orgId ?? null,
399	        duration_ms: durationMs,
400	        request_bytes: requestBytes,
401	        arguments: recordedArguments,
402	        intent: fields.intent,
403	        transport: ctx.http ? 'http' : 'stdio',
404	        protocol_version: protocolVersion,
405	        request_id:
406	          typeof requestId === 'string' || typeof requestId === 'number'
407	            ? boundedString(String(requestId), MAX_IDENTIFIER_LENGTH)
408	            : null,
409	        trace_id: trace?.traceId ?? null,
410	        parent_span_id: trace?.parentSpanId ?? null,
411	        read_only_hint: booleanOrNull(annotations?.readOnlyHint),
412	        destructive_hint: booleanOrNull(annotations?.destructiveHint),
413	        ...partial
414	      });
415	    };
416	
417	    // Only the handler call itself lives in this try: a throw here is a
418	    // protocol error the client receives as a JSON-RPC error, recorded and
419	    // re-thrown unchanged. Recording happens outside it so a telemetry
420	    // failure can never be mistaken for one.
421	    let result: ToolResultLike;
422	    try {
423	      result = (await handler(request, ctx)) as ToolResultLike;
424	    } catch (error) {
425	      const durationMs = Math.round(performance.now() - start);
426	      await guardedAsync(
427	        'event recording',
428	        async () => {
429	          const message = error instanceof Error ? error.message : String(error);
430	          const truncated = message.length > 2000 ? message.slice(0, 2000) : message;
431	          // The same rule the SDK uses to answer: the error's own integer
432	          // `code` (a ProtocolError's), otherwise internal error.
433	          const code = (error as { code?: unknown } | null)?.code;
434	          await push(durationMs, {
435	            success: false,
436	            error_kind: classifyError(truncated),
437	            error_message: truncated,
438	            response_bytes: 0,
439	            result_type: null,
440	            error_code: Number.isSafeInteger(code) ? (code as number) : INTERNAL_ERROR_CODE
441	          });
442	        },
443	        undefined
444	      );
445	      throw error;
446	    }
447	
448	    const durationMs = Math.round(performance.now() - start);
449	    await guardedAsync(
450	      'event recording',
451	      async () => {
452	        const responseBytes = guarded('response byte count', () => byteLength(result), 0);
453	        // Absent means complete: the SDK stamps `resultType` after this layer.
454	        const resultType = result?.resultType === 'input_required' ? 'input_required' : 'complete';
455	        if (result?.isError) {
456	          const errorMessage = extractErrorMessage(result);
457	          // A kind the handler declared wins; an unknown value falls back to the heuristic.
458	          // Guarded on its own so a throwing `_meta` costs only the declared kind, not the event.
459	          const declaredKind = guarded(
460	            'declared error kind',
461	            // `_meta` is the MCP protocol's field name.
462	            // oxlint-disable-next-line no-underscore-dangle
463	            () => result._meta?.[ERROR_KIND_META_KEY],
464	            undefined
465	          );
466	          await push(durationMs, {
467	            success: false,
468	            error_kind: isErrorKind(declaredKind) ? declaredKind : classifyError(errorMessage),
469	            error_message: errorMessage,
470	            response_bytes: responseBytes,
471	            result_type: resultType,
472	            error_code: null
473	          });
474	        } else {
475	          await push(durationMs, {
476	            success: true,
477	            error_kind: null,
478	            error_message: null,
479	            response_bytes: responseBytes,
480	            result_type: resultType,
